def parse_date(s):
    # supports MM/DD/YYYY and YYYY-MM-DD
    if '/' in s:
        m, d, y = s.split('/')
        return (int(y), int(m), int(d))
    y, m, d = s.split('-')
    return (int(y), int(m), int(d))

